23	export function getCurrentPosition(): Promise<{ lat: number; lon: number }> {
24	  return new Promise((resolve, reject) => {
25	    if (typeof navigator === "undefined" || !navigator.geolocation) {
26	      reject(new GeoError("unsupported"));
27	      return;
28	    }
29	    navigator.geolocation.getCurrentPosition(
30	      (p) => resolve({ lat: p.coords.latitude, lon: p.coords.longitude }),
31	      (e) => reject(new GeoError(kindFor(e.code))),
32	      { timeout: 10_000, maximumAge: 300_000 },
33	    );
34	  });
35	}
