41	export function resolveLocation(args: {
42	  input?: { lat: number; lon: number; label: string; source: LocationSource };
43	  profile?: ProfileLocation | null;
44	}): ResolvedLocation {
45	  const { input, profile } = args;
46	
47	  if (input) {
48	    return { lat: input.lat, lon: input.lon, label: input.label, origin: input.source };
49	  }
50	
51	  if (profile?.location_lat != null && profile.location_lon != null) {
52	    return {
53	      lat: profile.location_lat,
54	      lon: profile.location_lon,
55	      label: profile.location_label ?? "Current location",
56	      origin: "profile",
